package com.shahboun.aqim;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.location.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;

public class WorldLocationActivity extends Activity{
 final int G=Color.rgb(15,76,58),GD=Color.rgb(205,168,92),I=Color.rgb(248,244,235),T=Color.rgb(35,48,43),M=Color.rgb(105,110,108);android.graphics.Typeface c;LinearLayout root;SharedPreferences pref;
 static final LinkedHashMap<String,double[]> LIBYA_CITIES=new LinkedHashMap<>();static{LIBYA_CITIES.put("طرابلس",new double[]{32.8872,13.1913});LIBYA_CITIES.put("بنغازي",new double[]{32.1167,20.0667});LIBYA_CITIES.put("مصراتة",new double[]{32.3754,15.0925});LIBYA_CITIES.put("الزاوية",new double[]{32.7571,12.7276});LIBYA_CITIES.put("سبها",new double[]{27.0377,14.4283});LIBYA_CITIES.put("البيضاء",new double[]{32.7627,21.7551});LIBYA_CITIES.put("درنة",new double[]{32.7670,22.6367});LIBYA_CITIES.put("طبرق",new double[]{32.0836,23.9764});LIBYA_CITIES.put("غريان",new double[]{32.1722,13.0203});LIBYA_CITIES.put("زليتن",new double[]{32.4674,14.5687});LIBYA_CITIES.put("الخمس",new double[]{32.6486,14.2619});LIBYA_CITIES.put("صبراتة",new double[]{32.7934,12.4885});LIBYA_CITIES.put("صرمان",new double[]{32.7567,12.5716});LIBYA_CITIES.put("زوارة",new double[]{32.9312,12.0810});LIBYA_CITIES.put("ترهونة",new double[]{32.4350,13.6332});LIBYA_CITIES.put("بني وليد",new double[]{31.7566,13.9942});LIBYA_CITIES.put("سرت",new double[]{31.2089,16.5887});LIBYA_CITIES.put("أجدابيا",new double[]{30.7554,20.2263});LIBYA_CITIES.put("المرج",new double[]{32.4926,20.8291});LIBYA_CITIES.put("شحات",new double[]{32.8281,21.8624});LIBYA_CITIES.put("غدامس",new double[]{30.1337,9.5007});LIBYA_CITIES.put("مرزق",new double[]{25.9155,13.9184});}
 int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}GradientDrawable bg(int color,int r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(r));g.setStroke(dp(1),Color.rgb(232,221,194));return g;}TextView tx(String s,int z,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setPadding(dp(7),dp(7),dp(7),dp(7));if(c!=null)t.setTypeface(c,bold?1:0);return t;}Button bt(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setGravity(Gravity.CENTER);b.setTextColor(primary?Color.WHITE:T);b.setBackground(bg(primary?G:Color.WHITE,18));b.setElevation(dp(3));b.setMinHeight(0);b.setMinimumHeight(0);if(c!=null)b.setTypeface(c,1);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);pref=getSharedPreferences("aqim",0);getWindow().setStatusBarColor(I);getWindow().setNavigationBarColor(I);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception ignored){}migrateLegacyLocation();show();}
 void migrateLegacyLocation(){double lat=pref.getFloat("lat",32.8872f),lon=pref.getFloat("lon",13.1913f);if(!LibyaPrayerTables.isLibya(lat,lon))pref.edit().putString("city","طرابلس").putFloat("lat",32.8872f).putFloat("lon",13.1913f).putString("tzId","Africa/Tripoli").putString("locationMode","gps").apply();}
 void show(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(16),dp(16),dp(34));root.setBackgroundColor(I);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(tx("الموقع داخل ليبيا",28,G,true));root.addView(tx("هذا الإصدار مخصص لليبيا. GPS يحدد موقعك داخل ليبيا فقط ويختار أقرب مدينة/منطقة لاستخدام جدول المواقيت المحلي المحفوظ داخل أَقِم.",13,M,false));Button gps=bt("تحديد مدينتي تلقائيًا عبر GPS",true);gps.setOnClickListener(v->gps());add(gps);Button city=bt("اختيار مدينة ليبية يدويًا",false);city.setOnClickListener(v->chooseLibyaCity());add(city);String mode=pref.getString("locationMode","gps");root.addView(tx("الموقع المعتمد\n"+pref.getString("city","طرابلس")+"\nAfrica/Tripoli\nالوضع: "+("manual".equals(mode)?"اختيار يدوي":"GPS داخل ليبيا"),15,T,true));root.addView(tx("إذا كان الجهاز خارج حدود ليبيا فلن يتم اعتماد الموقع الجديد في هذا الإصدار.",12,M,false));ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(root);if(Build.VERSION.SDK_INT>=21)s.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets z=i.getInsets(WindowInsets.Type.systemBars());top=z.top;bottom=z.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return i;});setContentView(s);}
 void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58));p.setMargins(0,dp(7),0,0);root.addView(v,p);}
 void chooseLibyaCity(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(14),dp(14),dp(14));box.setBackground(bg(I,22));box.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);box.addView(tx("اختر المدينة",22,G,true));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);for(Map.Entry<String,double[]>e:LIBYA_CITIES.entrySet()){Button b=bt(e.getKey(),false);b.setOnClickListener(v->{double[]ll=e.getValue();save(e.getKey(),ll[0],ll[1],"manual");});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(2),0,dp(2));list.addView(b,p);}ScrollView sc=new ScrollView(this);sc.addView(list);box.addView(sc,new LinearLayout.LayoutParams(-1,dp(430)));Dialog d=new Dialog(this);d.setContentView(box);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}}
 void gps(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},91);return;}try{LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);boolean enabled=false;for(String x:lm.getProviders(true))if(LocationManager.GPS_PROVIDER.equals(x)||LocationManager.NETWORK_PROVIDER.equals(x))enabled=true;if(!enabled){Toast.makeText(this,"فعّل خدمة الموقع GPS ثم حاول مجددًا",Toast.LENGTH_LONG).show();return;}Location best=null;for(String p:lm.getProviders(true)){Location l=lm.getLastKnownLocation(p);if(l!=null&&(best==null||l.getTime()>best.getTime()||l.getAccuracy()<best.getAccuracy()))best=l;}if(best!=null&&System.currentTimeMillis()-best.getTime()<10*60*1000L){applyGps(best);return;}final LocationListener listener=new LocationListener(){boolean done=false;public void onLocationChanged(Location l){if(done||l==null)return;done=true;try{lm.removeUpdates(this);}catch(Exception ignored){}applyGps(l);}public void onProviderEnabled(String s){}public void onProviderDisabled(String s){}public void onStatusChanged(String p,int s,Bundle b){}};if(lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER))lm.requestSingleUpdate(LocationManager.NETWORK_PROVIDER,listener,Looper.getMainLooper());else lm.requestSingleUpdate(LocationManager.GPS_PROVIDER,listener,Looper.getMainLooper());new Handler(Looper.getMainLooper()).postDelayed(()->{try{lm.removeUpdates(listener);}catch(Exception ignored){}},12000);}catch(Exception e){Toast.makeText(this,"تعذر تحديد الموقع",Toast.LENGTH_LONG).show();}}
 void applyGps(Location l){double lat=l.getLatitude(),lon=l.getLongitude();if(!LibyaPrayerTables.isLibya(lat,lon)){Toast.makeText(this,"هذا الإصدار يعمل داخل ليبيا فقط. لم يتم تغيير موقعك المعتمد.",Toast.LENGTH_LONG).show();return;}String name=nearestCityName(lat,lon);try{List<Address>a=new Geocoder(this,new Locale("ar")).getFromLocation(lat,lon,1);if(a!=null&&!a.isEmpty()){Address x=a.get(0);String cc=x.getCountryCode();if(cc!=null&&!"LY".equalsIgnoreCase(cc)){Toast.makeText(this,"الموقع الحالي خارج ليبيا. لم يتم اعتماده.",Toast.LENGTH_LONG).show();return;}String n=x.getLocality()!=null?x.getLocality():x.getAdminArea();if(n!=null&&!n.trim().isEmpty())name=n;}}catch(Exception ignored){}save("GPS • "+name,lat,lon,"gps");}
 String nearestCityName(double lat,double lon){String best="طرابلس";float bd=Float.MAX_VALUE;float[]r=new float[1];for(Map.Entry<String,double[]>e:LIBYA_CITIES.entrySet()){double[]x=e.getValue();Location.distanceBetween(lat,lon,x[0],x[1],r);if(r[0]<bd){bd=r[0];best=e.getKey();}}return best;}
 void save(String name,double lat,double lon,String mode){pref.edit().putString("city",name).putFloat("lat",(float)lat).putFloat("lon",(float)lon).putString("tzId","Africa/Tripoli").putString("locationMode",mode).putBoolean("autoTravelLocation",true).apply();MainActivity.scheduleAll(this);PrayerWidget.updateAll(this);Toast.makeText(this,"تم اعتماد "+name,Toast.LENGTH_LONG).show();show();}
 @Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==91&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)gps();}
}
